from taf.internal.gnb.oam.coam.vdu.client.fh.v1 import (
    ApiClient,
    Configuration,
    Get1DWeightData,
    GetBeamData,
    GetDirectionData,
    GetWeightData,
    InlineObject2,
    VduWebemApi,
    ApiException
)

from taf.gnb.oam.coam.vdu.services.fh.http_client import FHv1HttpClient
from taf.gnb.oam.coam.vdu.utilities.logger import log_request_response
from taf.gnb.oam.coam.vdu.utilities.poll_status import poll_status
from taf.gnb.oam.coam.vdu.utilities.token_provider import auto_token_refresh
from taf.gnb.oam.coam.vdu.utilities.token_storage import TokenStorage
from taf.gnb.oam.coam.vdu.services.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.vdu.services.sec.sec_licensed_v1 import SECLicensedv1


@auto_token_refresh(api_exception=ApiException)
class FHv1:
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        conf = Configuration()
        conf.verify_ssl = False
        conf.host = con_details.get_api_client_configuration(original_endpoint=conf.host)
        self.configuration = conf

        api_client = ApiClient(configuration=conf)
        api_client.request = log_request_response(api_client.request)

        self.vdu_webem_api = VduWebemApi(api_client=api_client)
        self.local_client = FHv1HttpClient(base_url=con_details.base_url,
                                           connection_alias=con_details.alias)

    def get_alds_selection_mode(self, timeout=30):
        return self.local_client.get_alds_selection_mode(timeout=timeout)

    def get_ald_select_mode_operation_status(self, operation_id, timeout=30):
        return self.local_client.get_ald_select_mode_operation_status(operation_id=operation_id, timeout=timeout)

    def trigger_ald_selection_mode(self, ald_selection_mode, timeout=30):
        return self.local_client.trigger_ald_selection_mode(ald_selection_mode=ald_selection_mode, timeout=timeout)

    def set_ret_configuration(self, target_dn="", timeout=30, **kwargs):
        return self.local_client.set_ret_configuration(target_dn=target_dn, timeout=timeout, **kwargs)

    def get_ret_configuration_status(self, operation_id, timeout=30):
        return self.vdu_webem_api.get_ret_configuration(operation_id=operation_id, _request_timeout=timeout)

    def create_ald_reset(self, target_dn, type='soft', timeout=30):
        return self.local_client.create_ald_reset(target_dn=target_dn, type=type, timeout=timeout)

    def get_ald_reset_status(self, operation_id, timeout=30):
        return self.local_client.get_ald_reset_status(operation_id=operation_id, timeout=timeout)

    def upload_weight_factor_file(self, weight_file_path, target_dn, timeout=30):
        return self.vdu_webem_api.post_download_rae_weight_factor_file(weight_file=weight_file_path, target_dn=target_dn,
                                                                       _request_timeout=timeout)

    def get_upload_weight_factor_file_operation(self, operation_id, timeout=30):
        return self.local_client.get_upload_weight_factor_file_operation(operation_id=operation_id, timeout=timeout)

    def delete_upload_weight_factor_file_operation(self, operation_id, timeout=30):
        return self.vdu_webem_api.delete_download_rae_weight_factor_file_operation(operation_id=operation_id,
                                                                                   _request_timeout=timeout)

    def trigger_to_get_beam_data(self, target_dn, low_frequency, high_frequency, timeout=30):
        get_beam_data = GetBeamData(target_dn=target_dn, low_frequency=low_frequency, high_frequency=high_frequency)
        return self.vdu_webem_api.post_get_beam_data(get_beam_data=get_beam_data, _request_timeout=timeout)

    def get_beam_data_operation(self, operation_id, timeout=30):
        return self.local_client.get_beam_data_operation(operation_id=operation_id, timeout=timeout)

    def delete_get_beam_data_operation(self, operation_id, timeout=30):
        return self.vdu_webem_api.delete_get_beam_data_operation(operation_id=operation_id, _request_timeout=timeout)

    def trigger_to_get_direction_data(self, target_dn, low_frequency, high_frequency, horizontal_beamwidth,
                                      vertical_beamwidth, timeout=30):
        get_direction_data = GetDirectionData(target_dn=target_dn, low_frequency=low_frequency,
                                              high_frequency=high_frequency, horizontal_beamwidth=horizontal_beamwidth,
                                              vertical_beamwidth=vertical_beamwidth)
        return self.vdu_webem_api.post_get_direction_data(get_direction_data=get_direction_data, _request_timeout=timeout)

    def get_direction_data_operation(self, operation_id, timeout=30):
        return self.local_client.get_direction_data_operation(operation_id=operation_id, timeout=timeout)

    def delete_get_direction_data_operation(self, operation_id, timeout=30):
        return self.vdu_webem_api.delete_get_direction_data_operation(operation_id=operation_id, _request_timeout=timeout)

    def trigger_to_get_weight_data(self, target_dn, low_frequency, high_frequency, horizontal_beamwidth,
                                   vertical_beamwidth, azimuth, tilt, timeout=30):
        get_weight_data = GetWeightData(target_dn=target_dn, low_frequency=low_frequency, high_frequency=high_frequency,
                                        horizontal_beamwidth=horizontal_beamwidth,
                                        vertical_beamwidth=vertical_beamwidth, azimuth=azimuth, tilt=tilt)
        return self.vdu_webem_api.post_get_weight_data(get_weight_data=get_weight_data, _request_timeout=timeout)

    def get_weight_data_operation(self, operation_id, timeout=30):
        return self.local_client.get_weight_data_operation(operation_id=operation_id, timeout=timeout)

    def delete_get_weight_data_operation(self, operation_id, timeout=30):
        return self.vdu_webem_api.delete_get_weight_data_operation(operation_id=operation_id, _request_timeout=timeout)

    def restore_weight_factors_to_default_values(self, target_dn, timeout=30):
        inline_object2 = InlineObject2(target_dn=target_dn)
        return self.vdu_webem_api.post_reset_rae_weight_factors(inline_object2=inline_object2, _request_timeout=timeout)

    def get_operation_state_of_restoring_weight_factors(self, operation_id, timeout=30):
        return self.local_client.get_operation_state_of_restoring_weight_factors(operation_id=operation_id,
                                                                                 timeout=timeout)

    def delete_operation_of_restoring_weight_factors(self, operation_id, timeout=30):
        return self.vdu_webem_api.delete_reset_rae_weight_factors_operation(operation_id=operation_id,
                                                                            _request_timeout=timeout)

    def read_sensor_data(self, target_dn, timeout=30):
        return self.vdu_webem_api.alds_raes_operations_read_sensor_data_post(target_dn=target_dn,
                                                                             _request_timeout=timeout)

    def get_operation_of_reading_sensor_data(self, operation_id, timeout=30):
        return self.local_client.get_operation_of_reading_sensor_data(operation_id=operation_id, timeout=timeout)

    def delete_read_sensor_data_operation(self, operation_id, timeout=30):
        return self.vdu_webem_api.alds_raes_operations_read_sensor_data_operation_id_delete(operation_id=operation_id,
                                                                                            _request_timeout=timeout)

    def trigger_get_1d_weight_data(self, target_dn, electrical_tilt, broadcast_beam_width, low_frequency,
                                   high_frequency, timeout=30):
        get1_d_weight_data = Get1DWeightData(target_dn=target_dn, electrical_tilt=int(electrical_tilt),
                                             broadcast_beam_width=int(broadcast_beam_width),
                                             low_frequency=int(low_frequency),
                                             high_frequency=int(high_frequency))
        return self.vdu_webem_api.alds_raes_operations_get1d_weight_data_post(get1_d_weight_data=get1_d_weight_data,
                                                                              _request_timeout=timeout)

    def get_1d_weight_data(self, operation_id, timeout=30):
        return self.local_client.get_1d_weight_data(operation_id=operation_id, timeout=timeout)

    def delete_get_1d_weight_data_operation(self, operation_id, timeout=30):
        return self.vdu_webem_api.alds_raes_operations_get1d_weight_data_operation_id_delete(operation_id=operation_id,
                                                                                             _request_timeout=timeout)

    def get_rae_antenna_parameters(self, target_dn, timeout=30):
        return self.vdu_webem_api.get_rae_antenna_parameters(target_dn=target_dn, _request_timeout=timeout)

    def get_vswr_band(self, rmod_dn, ant_port_id, timeout=30):
        return self.vdu_webem_api.vswr_vswr_band_get(rmod_dn=rmod_dn, ant_port_id=ant_port_id, _request_timeout=timeout)

    def get_real_time_measurements_info(self, timeout=30):
        return self.local_client.get_real_time_measurements_info(timeout=timeout)

    def clear_rf_statistics_diagnostic_test_results(self, timeout=30):
        return self.local_client.clear_rf_statistics_diagnostic_test_results(timeout=timeout)

    def reset_rmods(self, rmods_list, reset_reason='user', graceful_cell_shutdown=False, wait_for_completion=False, timeout=30):
        operation = self.local_client.reset_rmods(rmods_list=rmods_list, reset_reason=reset_reason,
                                             graceful_cell_shutdown=graceful_cell_shutdown, timeout=timeout)

        if wait_for_completion:
            method_name = "get_status_of_reset_rmods"

            operation = poll_status(instance=self.local_client, method_name=method_name,
                               operation_id=operation["id"], timeout=timeout)

        return operation

    def get_reset_rmods_operation_status(self, operation_id, timeout=30):
        return self.local_client.get_status_of_reset_rmods(operation_id=operation_id, timeout=timeout)

    def update_tx_power_thresholds(self, thresholds):
        return self.local_client.update_tx_power_thresholds(thresholds=thresholds)
